import random
random.seed(3)
n=300; a=[random.randint(-50,50) for _ in range(n)]; T=RangeTree(a)
for _ in range(3000):
    l=random.randint(0,n-1); r=random.randint(l+1,n); op=random.randrange(5)
    if op==0: d=random.randint(-9,9); T.add(l,r,d); a[l:r]=[x+d for x in a[l:r]]
    elif op==1: v=random.randint(-30,30); T.assign(l,r,v); a[l:r]=[v]*(r-l)
    elif op==2: assert T.range_min(l,r)==min(a[l:r])
    elif op==3: assert T.range_sum(l,r)==sum(a[l:r])
    else: i=random.randrange(n); assert T.get(i)==a[i]
random.seed(9); n=200000; T=RangeTree([random.randint(-1000,1000) for _ in range(n)]); acc=0
import time; t0=time.time()
for _ in range(60000):
    l=random.randint(0,n-1); r=random.randint(l+1,n); op=random.randrange(4)
    if op==0: T.add(l,r,random.randint(-5,5))
    elif op==1: T.assign(l,r,random.randint(-100,100))
    elif op==2: acc=(acc+T.range_min(l,r))%1000000007
    else: acc=(acc+T.range_sum(l,r))%1000000007
assert time.time()-t0<25, 'too slow'
assert acc==960941717, acc

